parameters.jsCode:
// Собираем все сделки из всех страниц пагинации
const allItems = $('Get Filtered Deals').all();
const allDeals = [];

for (const item of allItems) {
  const data = item.json.data;
  if (Array.isArray(data)) {
    allDeals.push(...data);
  }
}

// Группируем по владельцу
const byOwner = {};

for (const deal of allDeals) {
  const ownerName = deal.owner_name || deal.user_id?.name || 'Unknown';
  const ownerId = deal.user_id?.id || deal.creator_user_id?.id || 0;

  if (!byOwner[ownerName]) {
    byOwner[ownerName] = {
      owner_id: ownerId,
      owner_name: ownerName,
      total: 0,
      won: 0,
      lost: 0,
      open: 0,
      won_value: 0,
      lost_value: 0,
      open_value: 0
    };
  }

  const o = byOwner[ownerName];
  o.total++;

  const value = deal.value || 0;
  if (deal.status === 'won') {
    o.won++;
    o.won_value += value;
  } else if (deal.status === 'lost') {
    o.lost++;
    o.lost_value += value;
  } else if (deal.status === 'open') {
    o.open++;
    o.open_value += value;
  }
}

// Считаем конверсию
const report = Object.values(byOwner).map(o => ({
  ...o,
  conversion_rate: o.total > 0 ? Math.round((o.won / o.total) * 10000) / 100 : 0,
  loss_rate: o.total > 0 ? Math.round((o.lost / o.total) * 10000) / 100 : 0
}));

// Итого
const totals = report.reduce((acc, o) => {
  acc.total += o.total;
  acc.won += o.won;
  acc.lost += o.lost;
  acc.open += o.open;
  acc.won_value += o.won_value;
  acc.lost_value += o.lost_value;
  acc.open_value += o.open_value;
  return acc;
}, { total: 0, won: 0, lost: 0, open: 0, won_value: 0, lost_value: 0, open_value: 0 });

totals.conversion_rate = totals.total > 0 ? Math.round((totals.won / totals.total) * 10000) / 100 : 0;
totals.loss_rate = totals.total > 0 ? Math.round((totals.lost / totals.total) * 10000) / 100 : 0;

return [{
  json: {
    report_name: 'Конверсія угод у воронці "Теплі ліди"',
    period: '01/01/2026 - 12/31/2026',
    generated_at: new Date().toISOString(),
    totals: totals,
    by_owner: report.sort((a, b) => b.total - a.total)
  }
}];
